INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 32, 'theory', 'Quiz: ast, eval, exec and dis');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 32, 0, 'What does ast.literal_eval(''[1, 2, 3]'') do?', '["Executes arbitrary code", "Safely parses a literal and returns a list", "Sums the numbers", "Raises SyntaxError"]', 1, 'literal_eval understands only literals (numbers, strings, lists, dicts, sets, tuples) and does not call functions.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 32, 1, 'How does compile differ from exec?', '["It doesn''t", "compile executes code, exec only parses it", "compile only turns text into a code object, which can then be executed many times", "exec works only with files"]', 2, 'compile returns a code object; eval/exec run it, and the text does not need to be parsed again.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 32, 2, 'How do you safely evaluate an arithmetic expression typed by a user?', '["eval with an empty names dict", "Remove the words import and exec from the string", "Parse it into an ast tree and allow only known nodes (numbers and operations)", "Run it in a separate thread"]', 2, 'String filters can be bypassed, while a whitelist of nodes relies on the grammar of the language.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 32, 3, 'What does the visit_BinOp method of a NodeTransformer return?', '["Always None", "A string of source code", "The result of evaluating the expression", "A new node that replaces the old one (or None to delete it)"]', 3, 'NodeTransformer replaces nodes; after changes you need fix_missing_locations, and ast.unparse returns the text.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 32, 4, 'What is the dis module for?', '["To speed up a program", "To read stack machine instructions and understand what code turns into", "To sign code", "To disable optimizations"]', 1, 'dis.dis prints the bytecode; the instruction set changes between versions, so production code should not rely on the names.');
